t = int(input())
for i in range(t):
	(n, k, f) = map(int, input().split())
	l = []
	for j in range(n):
		(a, b) = map(int, input().split())
		l.append((a, b))
	l.sort()
	(a, b) = l[0]
	if a > 0:
		ans += a
	else:
		ans = 0
	s = b
	for x in range(1, n):
		(a, b) = l[x]
		if a >= s:
			ans += a - s
		if s < b:
			s = b
	if s < f:
		ans += f - s
	if ans >= k:
		print('YES')
	else:
		print('NO')
